CREATE TABLE catalogo_equipamentos (
    chave                   VARCHAR(60)  PRIMARY KEY,
    nome                    VARCHAR(80)  NOT NULL,
    nome_busca              VARCHAR(80)  NOT NULL,
    versao_regras           VARCHAR(20)  NOT NULL DEFAULT 'SRD 5.1',
    categoria               VARCHAR(30)  NOT NULL,
    subcategoria            VARCHAR(40)  NOT NULL,
    quantidade              INT          NOT NULL DEFAULT 1,
    preco_pc                INT          NOT NULL,
    peso_kg                 NUMERIC(7,3) NOT NULL,
    dano                    VARCHAR(10),
    tipo_dano               VARCHAR(20),
    propriedades            VARCHAR(200),
    classe_armadura         INT,
    soma_destreza           BOOLEAN,
    destreza_maxima         INT,
    forca_minima            INT,
    desvantagem_furtividade BOOLEAN      NOT NULL DEFAULT FALSE,

    CONSTRAINT uk_catalogo_equipamentos_nome UNIQUE (nome),
    CONSTRAINT ck_catalogo_equipamentos_categoria
        CHECK (categoria IN ('ARMA', 'ARMADURA', 'EQUIPAMENTO_DE_AVENTURA', 'FERRAMENTA')),
    CONSTRAINT ck_catalogo_equipamentos_quantidade CHECK (quantidade > 0),
    CONSTRAINT ck_catalogo_equipamentos_preco CHECK (preco_pc >= 0),
    CONSTRAINT ck_catalogo_equipamentos_peso CHECK (peso_kg >= 0)
);

CREATE INDEX idx_catalogo_equipamentos_nome_busca ON catalogo_equipamentos (nome_busca varchar_pattern_ops);
CREATE INDEX idx_catalogo_equipamentos_categoria ON catalogo_equipamentos (categoria);

